1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ec; font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; flex-wrap: wrap; justify-content: center; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; padding: 1px; background: #262a33; border: 2px solid #3a3f4b; border-radius: 4px;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #0d0f14; }
20	  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18), inset 0 -3px 0 rgba(0,0,0,0.25); }
21	  .panel { display: flex; flex-direction: column; gap: 14px; min-width: 150px; }
22	  .stat { background: #1c1f27; border: 1px solid #2c313c; border-radius: 6px; padding: 8px 12px; }
23	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9097a6; }
24	  .stat .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
25	  .next-list { display: flex; flex-direction: column; gap: 8px; margin-top: 6px; }
26	  .preview { display: grid; grid-template-columns: repeat(4, 20px); grid-template-rows: repeat(2, 20px); gap: 1px; }
27	  .preview .mini { width: 20px; height: 20px; background: transparent; }
28	  .preview .mini[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
29	  .status { min-height: 1.4em; color: #ff8a80; font-weight: 600; }
30	  .help { font-size: 13px; color: #9097a6; }
31	  .help kbd { background: #2c313c; border-radius: 3px; padding: 0 5px; color: #e8e8ec; font: inherit; }
32	  button {
33	    background: #3a6ff7; color: #fff; border: 0; border-radius: 6px; padding: 8px 12px;
34	    font: inherit; font-weight: 600; cursor: pointer;
35	  }
36	</style>
37	</head>
38	<body>
39	<div class="game">
40	  <div class="board" data-testid="board"></div>
41	  <div class="panel">
42	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score">0</div></div>
43	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level">1</div></div>
44	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines">0</div></div>
45	    <div class="stat"><div class="label">Next</div><div class="next-list" data-testid="next-piece"></div></div>
46	    <div class="status" data-testid="status"><span data-testid="game-over" hidden></span></div>
47	    <button type="button" id="new-game">New game</button>
48	    <div class="help">
49	      <kbd>←</kbd> <kbd>→</kbd> move<br>
50	      <kbd>↑</kbd> rotate<br>
51	      <kbd>↓</kbd> soft drop<br>
52	      <kbd>Space</kbd> hard drop
53	    </div>
54	  </div>
55	</div>
56	<script>
57	(function () {
58	  'use strict';
59	
60	  var ROWS = 20, COLS = 10;
61	  var TYPES = ['I', 'O', 'T', 'S', 'Z', 'J', 'L'];
62	  var COLORS = {
63	    I: '#00bcd4', O: '#f5c400', T: '#9c27b0', S: '#43a047',
64	    Z: '#e53935', J: '#1e63d6', L: '#fb8c00'
65	  };
66	  // Spawn orientation, as [row, col] offsets from the piece origin.
67	  var SHAPES = {
68	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
69	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
70	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
71	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
72	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
73	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
74	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
75	  };
76	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
77	  var GRAVITY_MS = 1000;
78	  // Preview rule (a project decision): the panel shows only the next piece, in its colour.
79	  var PREVIEW_COUNT = 1;
80	
81	  // Clockwise rotation states. Each is a quarter turn of the one before, inside the
82	  // piece's box (2x2 for O, 3x3 for the rest). I is listed by hand so it turns about its middle.
83	  var ROTATIONS = {};
84	  TYPES.forEach(function (t) {
85	    var n = t === 'O' ? 2 : 3;
86	    var states = [SHAPES[t]];
87	    for (var k = 1; k < 4; k++) {
88	      states.push(states[k - 1].map(function (p) { return [p[1], n - 1 - p[0]]; }));
89	    }
90	    ROTATIONS[t] = states;
91	  });
92	  ROTATIONS.I = [
93	    SHAPES.I,
94	    [[0, 2], [1, 2], [2, 2], [3, 2]],
95	    [[1, 0], [1, 1], [1, 2], [1, 3]],
96	    [[0, 1], [1, 1], [2, 1], [3, 1]]
97	  ];
98	  // Sideways shifts tried, in order, when a rotated piece does not fit where it is.
99	  var KICKS = [0, -1, 1, -2, 2];
100	
101	  // Locking rule (a project decision): a gravity step that cannot move the piece down counts
102	  // one tick of lock delay; the piece locks on the LOCK_TICKS-th such tick. A successful left or
103	  // right move during the delay restarts it, and so does a soft drop on a piece that is already
104	  // resting; these share one cap of MAX_RESTARTS per piece. A soft drop that cannot move the piece
105	  // never counts a tick. Hard drop locks at once.
106	  var LOCK_TICKS = 2;
107	  var MAX_RESTARTS = 3;
108	
109	  // Scoring rule (a project decision): a clear scores LINE_POINTS[rows cleared at once] times the
110	  // current level. Clearing rows together must always beat clearing the same rows in smaller
111	  // groups, so every entry must exceed any sum of smaller entries that adds up to the same rows.
112	  // Soft drop scores 1 per cell moved down by the player; hard drop scores 2 per cell dropped.
113	  var LINE_POINTS = [0, 100, 300, 500, 800];
114	  var SOFT_DROP_POINTS = 1;
115	  var HARD_DROP_POINTS = 2;
116	
117	  // Game state. `board` holds the locked cells: a piece letter, or '' when empty.
118	  var board, current, queue, bag, score, level, lines, status, timer = null;
119	
120	  // ---- DOM ----
121	  var boardEl = document.querySelector('[data-testid="board"]');
122	  var scoreEl = document.querySelector('[data-testid="score"]');
123	  var levelEl = document.querySelector('[data-testid="level"]');
124	  var linesEl = document.querySelector('[data-testid="lines"]');
125	  var nextEl = document.querySelector('[data-testid="next-piece"]');
126	  var gameOverEl = document.querySelector('[data-testid="game-over"]');
127	  var cellEls = [];
128	  var itemEls = [];
129	  var miniEls = [];
130	
131	  for (var r = 0; r < ROWS; r++) {
132	    cellEls.push([]);
133	    for (var c = 0; c < COLS; c++) {
134	      var el = document.createElement('div');
135	      el.className = 'cell';
136	      el.setAttribute('data-testid', 'cell');
137	      el.setAttribute('data-row', String(r));
138	      el.setAttribute('data-col', String(c));
139	      boardEl.appendChild(el);
140	      cellEls[r].push(el);
141	    }
142	  }
143	  // One 4x2 mini grid per upcoming piece. The first grid keeps the older data-testid="next".
144	  for (var i = 0; i < PREVIEW_COUNT; i++) {
145	    var item = document.createElement('div');
146	    item.className = 'preview';
147	    item.setAttribute('data-testid', 'next-piece-item');
148	    nextEl.appendChild(item);
149	    itemEls.push(item);
150	    var grid = item;
151	    if (i === 0) {
152	      grid = document.createElement('div');
153	      grid.className = 'preview';
154	      grid.setAttribute('data-testid', 'next');
155	      item.className = '';
156	      item.appendChild(grid);
157	    }
158	    miniEls.push([]);
159	    for (var mr = 0; mr < 2; mr++) {
160	      miniEls[i].push([]);
161	      for (var mc = 0; mc < 4; mc++) {
162	        var m = document.createElement('div');
163	        m.className = 'mini';
164	        grid.appendChild(m);
165	        miniEls[i][mr].push(m);
166	      }
167	    }
168	  }
169	
170	  function paint(el, type) {
171	    el.setAttribute('data-filled', type ? 'true' : 'false');
172	    el.setAttribute('data-piece', type || '');
173	    el.style.backgroundColor = type ? COLORS[type] : '';
174	  }
175	
176	  function render() {
177	    var view = board.map(function (row) { return row.slice(); });
178	    if (current) {
179	      pieceCells(current).forEach(function (p) { view[p[0]][p[1]] = current.type; });
180	    }
181	    for (var r = 0; r < ROWS; r++) {
182	      for (var c = 0; c < COLS; c++) paint(cellEls[r][c], view[r][c]);
183	    }
184	
185	    for (var i = 0; i < PREVIEW_COUNT; i++) {
186	      var upcoming = queue[i] || '';
187	      itemEls[i].setAttribute('data-piece', upcoming);
188	      for (var mr = 0; mr < 2; mr++) {
189	        for (var mc = 0; mc < 4; mc++) paint(miniEls[i][mr][mc], '');
190	      }
191	      if (upcoming) {
192	        SHAPES[upcoming].forEach(function (p) { paint(miniEls[i][p[0]][p[1]], upcoming); });
193	      }
194	    }
195	
196	    scoreEl.textContent = String(score);
197	    levelEl.textContent = String(level);
198	    linesEl.textContent = String(lines);
199	    var over = status === 'gameover';
200	    gameOverEl.hidden = !over;
201	    gameOverEl.textContent = over ? 'Game over' : '';
202	  }
203	
204	  // ---- Pieces ----
205	  function randomPiece() {
206	    if (!bag.length) {
207	      bag = TYPES.slice();
208	      for (var i = bag.length - 1; i > 0; i--) {
209	        var j = Math.floor(Math.random() * (i + 1));
210	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
211	      }
212	    }
213	    return bag.pop();
214	  }
215	
216	  // Keep at least PREVIEW_COUNT pieces waiting, so the preview is always full.
217	  function fillQueue() {
218	    while (queue.length < PREVIEW_COUNT) queue.push(randomPiece());
219	  }
220	
221	  function takeNext() {
222	    fillQueue();
223	    var type = queue.shift();
224	    fillQueue();
225	    return type;
226	  }
227	
228	  function pieceCells(piece) {
229	    return ROTATIONS[piece.type][piece.rot].map(function (p) { return [piece.row + p[0], piece.col + p[1]]; });
230	  }
231	
232	  function fits(cells) {
233	    return cells.every(function (p) {
234	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !board[p[0]][p[1]];
235	    });
236	  }
237	
238	  function spawn() {
239	    var type = takeNext();
240	    var piece = { type: type, row: 0, col: SPAWN_COL[type], rot: 0, lockTicks: 0, restarts: 0 };
241	    if (!fits(pieceCells(piece))) {
242	      current = null;
243	      status = 'gameover';
244	      stopTimer();
245	      return;
246	    }
247	    current = piece;
248	  }
249	
250	  function move(dr, dc) {
251	    if (!current) return false;
252	    var moved = { type: current.type, row: current.row + dr, col: current.col + dc, rot: current.rot };
253	    if (!fits(pieceCells(moved))) return false;
254	    current.row = moved.row;
255	    current.col = moved.col;
256	    return true;
257	  }
258	
259	  // Left or right. During the lock delay, a successful move restarts it, up to the cap.
260	  function shift(dc) {
261	    if (move(0, dc)) restartLock();
262	  }
263	
264	  // Down, one row. On a piece already resting it counts no lock tick and restarts the delay like a
265	  // sideways move, sharing the same cap.
266	  function softDrop() {
267	    if (move(1, 0)) {
268	      current.lockTicks = 0;
269	      score += SOFT_DROP_POINTS;
270	    } else {
271	      restartLock();
272	    }
273	  }
274	
275	  function restartLock() {
276	    if (current.lockTicks > 0 && current.restarts < MAX_RESTARTS) {
277	      current.lockTicks = 0;
278	      current.restarts++;
279	    }
280	  }
281	
282	  // Try the next clockwise state in place, then shifted sideways. If nothing fits, change nothing.
283	  function rotateCW() {
284	    if (!current) return false;
285	    var rot = (current.rot + 1) % 4;
286	    for (var i = 0; i < KICKS.length; i++) {
287	      var turned = { type: current.type, row: current.row, col: current.col + KICKS[i], rot: rot };
288	      if (fits(pieceCells(turned))) {
289	        current.col = turned.col;
290	        current.rot = rot;
291	        return true;
292	      }
293	    }
294	    return false;
295	  }
296	
297	  // Remove every full row; the rows above drop down. Returns how many rows went.
298	  function clearLines() {
299	    var kept = board.filter(function (row) { return !row.every(Boolean); });
300	    var cleared = ROWS - kept.length;
301	    for (var i = 0; i < cleared; i++) kept.unshift(new Array(COLS).fill(''));
302	    board = kept;
303	    return cleared;
304	  }
305	
306	  function lock() {
307	    pieceCells(current).forEach(function (p) { board[p[0]][p[1]] = current.type; });
308	    current = null;
309	    var cleared = clearLines();
310	    lines += cleared;
311	    score += LINE_POINTS[cleared] * level;
312	    spawn();
313	  }
314	
315	  // One gravity step. The real timer and tick() both run exactly this. Returns true if the piece moved down.
316	  function gravityStep() {
317	    if (status !== 'running' || !current) return false;
318	    if (move(1, 0)) {
319	      current.lockTicks = 0;
320	      return true;
321	    }
322	    current.lockTicks++;
323	    if (current.lockTicks >= LOCK_TICKS) lock();
324	    return false;
325	  }
326	
327	  function gravity() {
328	    gravityStep();
329	    render();
330	  }
331	
332	  function stopTimer() {
333	    if (timer !== null) { clearInterval(timer); timer = null; }
334	  }
335	
336	  function startTimer() {
337	    stopTimer();
338	    timer = setInterval(gravity, GRAVITY_MS);
339	  }
340	
341	  // ---- Actions ----
342	  function input(action) {
343	    if (status !== 'running' || !current) return;
344	    if (action === 'left') shift(-1);
345	    else if (action === 'right') shift(1);
346	    else if (action === 'rotateCW') rotateCW();
347	    else if (action === 'softDrop') softDrop();
348	    else if (action === 'hardDrop') {
349	      while (move(1, 0)) score += HARD_DROP_POINTS;
350	      lock();
351	    }
352	    render();
353	  }
354	
355	  function toQueue(list) {
356	    return (Array.isArray(list) ? list : [])
357	      .map(function (t) { return String(t).toUpperCase(); })
358	      .filter(function (t) { return SHAPES.hasOwnProperty(t); });
359	  }
360	
361	  function newGame(list) {
362	    board = [];
363	    for (var r = 0; r < ROWS; r++) board.push(new Array(COLS).fill(''));
364	    bag = [];
365	    queue = toQueue(list);
366	    score = 0;
367	    level = 1;
368	    lines = 0;
369	    status = 'running';
370	    current = null;
371	    spawn();
372	    if (status === 'running') startTimer();
373	    render();
374	  }
375	
376	  function setQueue(list) {
377	    queue = toQueue(list);
378	    fillQueue();
379	    render();
380	  }
381	
382	  function setBoard(rows) {
383	    for (var r = 0; r < ROWS; r++) {
384	      var line = rows && typeof rows[r] === 'string' ? rows[r] : '';
385	      for (var c = 0; c < COLS; c++) {
386	        var ch = line.charAt(c).toUpperCase();
387	        board[r][c] = SHAPES.hasOwnProperty(ch) ? ch : '';
388	      }
389	    }
390	    render();
391	  }
392	
393	  function getBoard() {
394	    return board.map(function (row) {
395	      return row.map(function (t) { return t || '.'; }).join('');
396	    });
397	  }
398	
399	  function getState() {
400	    return {
401	      current: current ? { type: current.type, cells: pieceCells(current) } : null,
402	      next: queue.slice(),
403	      score: score,
404	      level: level,
405	      lines: lines,
406	      status: status
407	    };
408	  }
409	
410	  function tick(n) {
411	    var steps = n === undefined ? 1 : n;
412	    for (var i = 0; i < steps; i++) gravity();
413	  }
414	
415	  window.__tetris = {
416	    newGame: newGame,
417	    setQueue: setQueue,
418	    setBoard: setBoard,
419	    tick: tick,
420	    input: input,
421	    getBoard: getBoard,
422	    getState: getState
423	  };
424	
425	  var KEYS = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'rotateCW', ArrowDown: 'softDrop', ' ': 'hardDrop', Spacebar: 'hardDrop' };
426	  document.addEventListener('keydown', function (e) {
427	    var action = KEYS[e.key];
428	    if (!action) return;
429	    e.preventDefault();
430	    input(action);
431	  });
432	  document.getElementById('new-game').addEventListener('click', function (e) {
433	    e.currentTarget.blur();
434	    newGame();
435	  });
436	
437	  newGame();
438	})();
439	</script>
440	</body>
441	</html>
